mapper.select:
SELECT AS bucket, jt.dim_key AS dim_key, COUNT(DISTINCT CASE WHEN o.event_id IS NOT NULL AND () THEN es.id END) AS tp, COUNT(DISTINCT CASE WHEN o.event_id IS NOT NULL AND NOT () THEN es.id END) AS fp, COUNT(DISTINCT es.id) AS fired_total FROM evaluation_session es CROSS JOIN JSON_TABLE(es.hit_decisions, '$[*]' COLUMNS (dim_key VARCHAR(128) PATH
'$.code' '$.ruleVersionId'
)) jt LEFT JOIN decision_outcome o ON o.tenant_id = es.tenant_id AND o.event_id = es.event_id WHERE es.tenant_id = #{tenantId} AND es.scene_code = #{sceneCode} AND es.occurred_at >= #{from} AND es.occurred_at < #{to} AND jt.dim_key IS NOT NULL GROUP BY bucket, jt.dim_key
